CREATE TABLE property_portal_grants (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),managed_property_id TEXT NOT NULL REFERENCES managed_properties(id),contact_id TEXT NOT NULL REFERENCES contacts(id),audience TEXT NOT NULL CHECK(audience IN ('landlord','tenant')),email TEXT NOT NULL,token_hash TEXT NOT NULL,expires_at TEXT NOT NULL,accepted_user_id TEXT,accepted_at TEXT,revoked_at TEXT,invited_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_property_portal_grants_token ON property_portal_grants(token_hash);
CREATE INDEX idx_property_portal_grants_user ON property_portal_grants(accepted_user_id,revoked_at);
CREATE INDEX idx_property_portal_grants_property ON property_portal_grants(agency_id,managed_property_id,audience);
CREATE TABLE contractors (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),contact_id TEXT NOT NULL REFERENCES contacts(id),trade TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,notes TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_contractors_contact_trade ON contractors(agency_id,contact_id,trade);
CREATE TABLE maintenance_requests (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),managed_property_id TEXT NOT NULL REFERENCES managed_properties(id),lease_id TEXT REFERENCES leases(id),reported_by_contact_id TEXT REFERENCES contacts(id),category TEXT NOT NULL DEFAULT 'general',title TEXT NOT NULL,description TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'reported',contractor_id TEXT REFERENCES contractors(id),assigned_user_id TEXT,estimated_minor INTEGER,approved_minor INTEGER,actual_minor INTEGER,approval_status TEXT NOT NULL DEFAULT 'not_required',scheduled_at TEXT,completed_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_maintenance_property_status ON maintenance_requests(agency_id,managed_property_id,status,created_at);
CREATE TABLE maintenance_updates (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),request_id TEXT NOT NULL REFERENCES maintenance_requests(id),actor_user_id TEXT NOT NULL,status TEXT NOT NULL,note TEXT NOT NULL,private_to_agency INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_maintenance_updates_request ON maintenance_updates(agency_id,request_id,created_at);
CREATE TABLE maintenance_media_assets (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),request_id TEXT NOT NULL REFERENCES maintenance_requests(id),object_key TEXT NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_maintenance_media_object ON maintenance_media_assets(object_key);
CREATE INDEX idx_maintenance_media_request ON maintenance_media_assets(agency_id,request_id,created_at);
CREATE TABLE property_inspections (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),managed_property_id TEXT NOT NULL REFERENCES managed_properties(id),lease_id TEXT REFERENCES leases(id),inspection_type TEXT NOT NULL,scheduled_at TEXT NOT NULL,completed_at TEXT,summary TEXT NOT NULL DEFAULT '',private_media_prefix TEXT,status TEXT NOT NULL DEFAULT 'scheduled',assigned_user_id TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_inspections_property_date ON property_inspections(agency_id,managed_property_id,scheduled_at);
CREATE TABLE inspection_media_assets (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),inspection_id TEXT NOT NULL REFERENCES property_inspections(id),object_key TEXT NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL,caption TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_inspection_media_object ON inspection_media_assets(object_key);
CREATE INDEX idx_inspection_media_inspection ON inspection_media_assets(agency_id,inspection_id,created_at);
CREATE TABLE inspection_reports (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),inspection_id TEXT NOT NULL REFERENCES property_inspections(id),rooms_json TEXT NOT NULL DEFAULT '[]',meter_readings_json TEXT NOT NULL DEFAULT '[]',signatures_json TEXT NOT NULL DEFAULT '[]',snapshot TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'final',finalized_by TEXT NOT NULL,finalized_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_inspection_reports_inspection ON inspection_reports(inspection_id);
CREATE INDEX idx_inspection_reports_agency ON inspection_reports(agency_id,finalized_at);
CREATE TABLE lease_renewals (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),lease_id TEXT NOT NULL REFERENCES leases(id),proposed_rent_minor INTEGER NOT NULL,proposed_starts_at TEXT NOT NULL,proposed_ends_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',tenant_decision_at TEXT,finalized_lease_id TEXT REFERENCES leases(id),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_lease_renewals_open ON lease_renewals(agency_id,lease_id) WHERE status IN ('draft','offered','accepted');
CREATE INDEX idx_lease_renewals_status ON lease_renewals(agency_id,status,proposed_starts_at);
CREATE TABLE property_portal_updates (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),managed_property_id TEXT NOT NULL REFERENCES managed_properties(id),audience TEXT NOT NULL DEFAULT 'all',title TEXT NOT NULL,body TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_property_portal_updates_property ON property_portal_updates(agency_id,managed_property_id,created_at);
CREATE TABLE portal_document_shares (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),managed_property_id TEXT NOT NULL REFERENCES managed_properties(id),document_id TEXT NOT NULL REFERENCES documents(id),audience TEXT NOT NULL,shared_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_portal_document_shares_unique ON portal_document_shares(agency_id,managed_property_id,document_id,audience);
CREATE INDEX idx_portal_document_shares_property ON portal_document_shares(agency_id,managed_property_id,audience);
PRAGMA optimize;
